/* Element tables for the powder-grid simulation.
 *
 * Static properties are generated by scripts/extract_powder_toy.py from The Powder Toy
 * (GPL-3.0, https://github.com/The-Powder-Toy/The-Powder-Toy, commit recorded in the
 * JSON). Behaviour that is not a static property lives in ./behaviors.
 */
import raw from '../generated/powder-elements.json';

export const CELL = 4;
export const ISTP = CELL / 2;
export const CFDS = 4 / CELL;
export const MAX_VELOCITY = 1e4;
export const MAX_TEMP = 9999, MIN_TEMP = 0;
export const MAX_PRESSURE = 256, MIN_PRESSURE = -256;
export const R_TEMP = 22;
export const PMAPBITS = 9, PMAPMASK = (1 << PMAPBITS) - 1;
export const PT_NUM = 1 << PMAPBITS;
export const ST = PT_NUM, NT = -1;

export const ID = (r: number) => r >> PMAPBITS;
export const TYP = (r: number) => r & PMAPMASK;
export const PMAP = (id: number, typ: number) => (id << PMAPBITS) | (typ & PMAPMASK);

export interface ElementDef {
  id: number; key: string; name: string; description: string; colour: number;
  Advection: number; AirDrag: number; AirLoss: number; Loss: number; Collision: number; Gravity: number;
  NewtonianGravity: number; Diffusion: number; HotAir: number; Falldown: number; Flammable: number;
  Explosive: number; Meltable: number; Hardness: number; PhotonReflectWavelengths: number; Weight: number;
  HeatConduct: number; HeatCapacity: number; Properties: number; CarriesTypeIn: number;
  LowPressure: number; LowPressureTransition: number; HighPressure: number; HighPressureTransition: number;
  LowTemperature: number; LowTemperatureTransition: number; HighTemperature: number; HighTemperatureTransition: number;
  MenuVisible: number; MenuSection: number; MenuSort: number; Enabled: number;
  default: { temp: number; life?: number; ctype?: number; tmp?: number; tmp2?: number; tmp4?: number; vx?: number };
  hasUpdate: boolean; hasCreate: boolean;
}

export const SOURCE = { repository: raw.source, commit: raw.commit, license: raw.license };
const real = raw.elements as ElementDef[];
/** Number of element ids that exist upstream; ids up to PT_NUM exist as disabled placeholders, as in the original table. */
export const ELEMENT_COUNT = real.length;
export const ELEMENTS: ElementDef[] = [...real];
for (let id = real.length; id < PT_NUM; id++) {
  ELEMENTS.push({ ...real[0], id, key: '', name: '', description: '', Enabled: 0, MenuVisible: 0, hasUpdate: false, hasCreate: false });
}

const C = raw.constants as Record<string, number>;
export const TYPE_PART = C.TYPE_PART, TYPE_LIQUID = C.TYPE_LIQUID, TYPE_SOLID = C.TYPE_SOLID, TYPE_GAS = C.TYPE_GAS,
  TYPE_ENERGY = C.TYPE_ENERGY, PROP_CONDUCTS = C.PROP_CONDUCTS, PROP_PHOTPASS = C.PROP_PHOTPASS,
  PROP_NEUTPENETRATE = C.PROP_NEUTPENETRATE, PROP_NEUTABSORB = C.PROP_NEUTABSORB, PROP_NEUTPASS = C.PROP_NEUTPASS,
  PROP_DEADLY = C.PROP_DEADLY, PROP_RADIOACTIVE = C.PROP_RADIOACTIVE, PROP_LIFE_DEC = C.PROP_LIFE_DEC,
  PROP_LIFE_KILL = C.PROP_LIFE_KILL, PROP_LIFE_KILL_DEC = C.PROP_LIFE_KILL_DEC, PROP_NOAMBHEAT = C.PROP_NOAMBHEAT,
  PROP_SPARKSETTLE = C.PROP_SPARKSETTLE, PROP_HOT_GLOW = C.PROP_HOT_GLOW;
export const FLAG_STAGNANT = 1, FLAG_SKIPMOVE = 2, FLAG_MOVABLE = 8;

/** Element ids by PT_ name, e.g. PT.WATR. */
export const PT: Record<string, number> = Object.fromEntries(real.map(e => [e.key, e.id]));
export const PT_NONE = 0;

/** can_move[moving][destination]: 0 no move/bounce, 1 swap, 2 share space, 3 varies. Mirrors SimulationData::init_can_move. */
export function buildCanMove(): Uint8Array {
  const n = PT_NUM, cm = new Uint8Array(n * n), E = ELEMENTS;
  const has = (t: number) => t < E.length;
  const prop = (t: number) => has(t) ? E[t].Properties : 0;
  const weight = (t: number) => has(t) ? E[t].Weight : 0;
  const set = (a: number, b: number, v: number) => { cm[a * n + b] = v; };
  for (let m = 1; m < n; m++) for (let d = 0; d < n; d++) set(m, d, 1);
  for (let d = 1; d < n; d++) set(PT.PHOT, d, 2);
  for (let m = 1; m < n; m++) for (let d = 1; d < n; d++) {
    if (weight(m) <= weight(d) || d === PT.GEL) set(m, d, 0);
    if (m === PT.NEUT && prop(d) & PROP_NEUTPASS) set(m, d, 2);
    if (m === PT.NEUT && prop(d) & PROP_NEUTABSORB) set(m, d, 1);
    if (m === PT.NEUT && prop(d) & PROP_NEUTPENETRATE) set(m, d, 1);
    if (d === PT.NEUT && prop(m) & PROP_NEUTPENETRATE) set(m, d, 0);
    if (prop(m) & TYPE_ENERGY && prop(d) & TYPE_ENERGY) set(m, d, 2);
  }
  for (let d = 0; d < n; d++) {
    let stkm = 0;
    if (prop(d) & (TYPE_LIQUID | TYPE_GAS)) stkm = 2;
    if (!d || d === PT.PRTO || d === PT.SPAWN || d === PT.SPAWN2) stkm = 2;
    set(PT.STKM, d, stkm); set(PT.STKM2, d, stkm); set(PT.FIGH, d, stkm);
    set(PT.SPRK, d, 0);
  }
  for (let m = 1; m < n; m++) {
    set(m, PT.BHOL, 1); set(m, PT.NBHL, 1);
    set(m, PT.STKM, 0); set(m, PT.STKM2, 0); set(m, PT.FIGH, 0);
    set(m, PT.INVIS, 3); set(m, PT.CNCT, 0); set(m, PT.PVOD, 3); set(m, PT.VOID, 3);
    set(m, PT.EMBR, 0); set(PT.EMBR, m, 0);
    if (prop(m) & TYPE_ENERGY) { set(m, PT.VIBR, 1); set(m, PT.BVBR, 1); }
    if (prop(m) & TYPE_PART) set(m, PT.SAWD, 0);
  }
  for (let d = 0; d < n; d++) {
    if (prop(d) & PROP_PHOTPASS) set(PT.PHOT, d, 2);
    if (![PT.DMND, PT.INSL, PT.VOID, PT.PVOD, PT.VIBR, PT.BVBR, PT.PRTI, PT.PRTO].includes(d)) { set(PT.PROT, d, 2); set(PT.GRVT, d, 2); }
  }
  for (const t of [PT.DMND, PT.CLNE, PT.PCLN, PT.BCLN, PT.PBCN, PT.ROCK]) set(PT.DEST, t, 0);
  set(PT.NEUT, PT.INVIS, 2); set(PT.ELEC, PT.LCRY, 2); set(PT.ELEC, PT.EXOT, 2); set(PT.ELEC, PT.GLOW, 2);
  set(PT.PHOT, PT.LCRY, 3); set(PT.PHOT, PT.GPMP, 3);
  for (const t of [PT.BIZR, PT.BIZRG, PT.BIZRS]) { set(PT.PHOT, t, 2); set(PT.ELEC, t, 2); }
  set(PT.BIZR, PT.FILT, 2); set(PT.BIZRG, PT.FILT, 2);
  set(PT.ANAR, PT.WHOL, 1); set(PT.ANAR, PT.NWHL, 1); set(PT.ELEC, PT.DEUT, 1); set(PT.THDR, PT.THDR, 2);
  set(PT.EMBR, PT.EMBR, 2); set(PT.TRON, PT.SWCH, 3); set(PT.ELEC, PT.RSST, 2); set(PT.ELEC, PT.RSSS, 2);
  return cm;
}

export const WL = { ERASE: 0, WALLELEC: 1, EWALL: 2, DETECT: 3, STREAM: 4, FAN: 5, ALLOWLIQUID: 6, DESTROYALL: 7, WALL: 8,
  ALLOWAIR: 9, ALLOWPOWDER: 10, ALLOWALLELEC: 11, EHOLE: 12, ALLOWGAS: 13, GRAV: 14, ALLOWENERGY: 15, BLOCKAIR: 16,
  ERASEALL: 17, STASIS: 18 } as const;
